package org.sleepwell.app;
import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.util.*;
/** All imports and their change token share one SQLite transaction. No sensor rows are created. */
final class HealthSleepStore implements HealthSleepSync.Local {
 final Store store;final String epoch;HealthSleepStore(Store store){this.store=store;epoch=state("epoch");if(epoch.isEmpty())throw new IllegalStateException("Health Connect ownership is missing.");}
 public String token(){return state("token");}
 public void apply(List<HealthSleep> records,List<String> deleted,String next,String ownPackage,long now){applyBatch(records,deleted,next,ownPackage,now);}
 public List<RecordEntry> records(){check();return Records.all(store);}
 public int conflicts(){return store.rows("SELECT remote_id FROM health_imports WHERE status='conflict'").size();}
 String state(String key){List<JSONObject> rows=store.rows("SELECT value FROM health_state WHERE key=?",key);return rows.isEmpty()?"":rows.get(0).optString("value");}
 void check(){if(!epoch.equals(state("epoch")))throw new IllegalStateException("Sleep data was replaced while sync was running. Sync again.");}
 void value(String key,String text){ContentValues v=new ContentValues();v.put("key",key);v.put("value",text);if(store.getWritableDatabase().insertWithOnConflict("health_state",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new android.database.sqlite.SQLiteException("Sync status could not be stored.");}
 static String hash(String value){try{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));return java.util.Base64.getEncoder().encodeToString(bytes);}catch(java.security.NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
 String fingerprint(long id){RecordEntry r=Records.get(store,id);return hash(Records.display(r).toString()+"/"+r.updated);}
 boolean exists(long id){return id>0&&!store.rows("SELECT id FROM sessions WHERE id=?",""+id).isEmpty();}
 static boolean canonical(RecordEntry local,HealthSleep original){RecordDraft d=original.draft();if(local.rawStart!=original.start||local.rawEnd!=original.end||local.edit.start!=d.start||local.edit.end!=d.end||!local.edit.note.equals(d.note)||local.edit.rated||!local.edit.tags.isEmpty())return false;List<RecordIntervals.Span> a=RecordIntervals.union(local.edit.awake),b=RecordIntervals.union(d.awake);if(a.size()!=b.size())return false;for(int n=0;n<a.size();n++)if(a.get(n).start!=b.get(n).start||a.get(n).end!=b.get(n).end)return false;return true;}
 private int[] applyBatch(List<HealthSleep> records,List<String> deleted,String next,String ownPackage,long now){List<String> encoded=new ArrayList<>();for(HealthSleep r:records){if(r.end>now)throw new IllegalArgumentException("Health Connect returned an unfinished or future sleep period.");encoded.add(HealthSleepCodec.encode(r));}SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{check();int changed=0,removed=0;for(int n=0;n<records.size();n++){check();HealthSleep r=records.get(n);if(!r.origin.equals(ownPackage)&&upsert(r,encoded.get(n),now))changed++;}for(String id:deleted){check();if(deleted(id))removed++;}if(next!=null)value("token",next);check();db.setTransactionSuccessful();return new int[]{changed,removed};}finally{db.endTransaction();}}
 private boolean upsert(HealthSleep remote,String payload,long now){List<JSONObject> found=store.rows("SELECT * FROM health_imports WHERE remote_id=?",remote.id);JSONObject link=found.isEmpty()?null:found.get(0);long id=link==null?0:link.optLong("session");String status=link==null?"":link.optString("status");
  if(link!=null&&!link.optString("origin").equals(remote.origin))throw new IllegalArgumentException("Health Connect record source changed unexpectedly.");if(status.equals("hidden")||status.equals("kept"))return false;if(link!=null&&remote.modified<link.optLong("modified"))return false;
  if(link!=null&&id>0&&!exists(id)){hidden(remote.id);return false;}
  if(link==null){for(JSONObject row:store.rows("SELECT id,health_connect FROM sessions WHERE health_connect<>''")){HealthSleep previous=HealthSleepCodec.read(row.optString("health_connect"));if(previous!=null&&previous.id.equals(remote.id)&&previous.origin.equals(remote.origin)){id=row.optLong("id");if(!canonical(Records.get(store,id),previous)){link(remote,id,now,payload,"","conflict");return false;}break;}}}
  if(link!=null&&payload.equals(link.optString("payload"))&&status.equals("linked"))return false;
  if(id>0&&link!=null&&!fingerprint(id).equals(link.optString("fingerprint"))){link(remote,id,now,payload,link.optString("fingerprint"),"conflict");return false;}
  id=write(remote,payload,id,now);link(remote,id,now,payload,fingerprint(id),"linked");return true;
 }
 private long write(HealthSleep remote,String payload,long id,long now){SQLiteDatabase db=store.getWritableDatabase();ContentValues session=new ContentValues();session.put("start",remote.start);session.put("end",remote.end);session.put("source","manual");session.put("origin","imported");session.put("zone",remote.zone());session.put("sensor","none");session.put("sensor_config","");session.put("sound_analysis","");session.put("health_connect",payload);session.putNull("active_ms");session.put("note",remote.title);long updated=now;if(id==0)id=db.insertOrThrow("sessions",null,session);else{RecordEntry old=Records.get(store,id);if(old.healthConnect.isEmpty())throw new IllegalStateException("The imported record was replaced.");updated=Math.max(now,old.updated+1);if(db.update("sessions",session,"id=?",new String[]{""+id})!=1)throw new IllegalStateException("The imported record changed.");}if(db.insertWithOnConflict("record_edits",null,Records.values(id,remote.draft(),updated),SQLiteDatabase.CONFLICT_REPLACE)<0)throw new android.database.sqlite.SQLiteException("Imported sleep details could not be stored.");return id;}
 private void link(HealthSleep remote,long id,long now,String payload,String fingerprint,String status){ContentValues v=new ContentValues();v.put("remote_id",remote.id);v.put("origin",remote.origin);v.put("session",id);v.put("modified",remote.modified);v.put("payload",payload);v.put("fingerprint",fingerprint);v.put("status",status);if(store.getWritableDatabase().insertWithOnConflict("health_imports",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new android.database.sqlite.SQLiteException("Import identity could not be stored.");}
 private void hidden(String id){ContentValues v=new ContentValues();v.put("session",0);v.put("payload","");v.put("fingerprint","");v.put("status","hidden");store.getWritableDatabase().update("health_imports",v,"remote_id=?",new String[]{id});}
 private boolean deleted(String remoteId){List<JSONObject> rows=store.rows("SELECT * FROM health_imports WHERE remote_id=?",remoteId);if(rows.isEmpty())return false;JSONObject row=rows.get(0);String status=row.optString("status");if(Set.of("hidden","kept","deleted").contains(status))return false;long id=row.optLong("session");if(!exists(id)){hidden(remoteId);return false;}ContentValues update=new ContentValues();update.put("payload","");if(fingerprint(id).equals(row.optString("fingerprint"))){deleteOwned(id);update.put("session",0);update.put("fingerprint","");update.put("status","deleted");}else{update.put("status","conflict");}store.getWritableDatabase().update("health_imports",update,"remote_id=?",new String[]{remoteId});return true;}
 private void deleteOwned(long id){RecordEntry r=Records.get(store,id);if(r.healthConnect.isEmpty()||!r.manual()||!store.rows("SELECT id FROM epochs WHERE session=?",""+id).isEmpty()||!store.rows("SELECT id FROM clips WHERE session=?",""+id).isEmpty())throw new IllegalStateException("Only an unmeasured imported copy can be removed by sync.");SQLiteDatabase db=store.getWritableDatabase();db.delete("record_edits","session=?",new String[]{""+id});db.delete("sessions","id=?",new String[]{""+id});}
 void resolve(String remoteId,String expectedFingerprint,String expectedPayload,boolean useProvider,long now){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{check();List<JSONObject> found=store.rows("SELECT * FROM health_imports WHERE remote_id=? AND status='conflict'",remoteId);if(found.size()!=1)throw new IllegalStateException("This change is no longer waiting.");JSONObject row=found.get(0);long id=row.optLong("session");if(!exists(id)||!expectedFingerprint.equals(fingerprint(id))||!expectedPayload.equals(row.optString("payload")))throw new IllegalStateException("The local or provider record changed. Review again.");if(!useProvider){ContentValues v=new ContentValues();v.put("status","kept");v.put("payload","");store.getWritableDatabase().update("health_imports",v,"remote_id=?",new String[]{remoteId});}else if(expectedPayload.isEmpty()){deleteOwned(id);ContentValues v=new ContentValues();v.put("status","deleted");v.put("session",0);v.put("fingerprint","");db.update("health_imports",v,"remote_id=?",new String[]{remoteId});}else{HealthSleep remote=HealthSleepCodec.read(expectedPayload);write(remote,expectedPayload,id,now);link(remote,id,now,expectedPayload,fingerprint(id),"linked");}db.setTransactionSuccessful();}finally{db.endTransaction();}}
 void allowHidden(){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{check();db.delete("health_imports","status='hidden'",null);db.delete("health_state","key='token'",null);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 static String birth(RecordEntry r){return hash(r.rawStart+"/"+r.rawEnd+"/"+r.source+"/"+r.origin+"/"+r.healthConnect);}
 static final class Export {final String client,birth,fingerprint;final long session,version;final HealthSleep data;final boolean manual;Export(String client,long session,String birth,long version,String fingerprint,HealthSleep data,boolean manual){this.client=client;this.session=session;this.birth=birth;this.version=version;this.fingerprint=fingerprint;this.data=data;this.manual=manual;}}
 public Export prepare(RecordEntry r,String ownPackage){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{Export result=prepareInside(r,ownPackage);db.setTransactionSuccessful();return result;}finally{db.endTransaction();}}
 private Export prepareInside(RecordEntry r,String ownPackage){check();r=Records.get(store,r.id);if(!r.healthConnect.isEmpty())return null;String signature=birth(r),fp=fingerprint(r.id);List<JSONObject> saved=store.rows("SELECT * FROM health_exports WHERE session=? AND birth=?",""+r.id,signature);JSONObject old=saved.isEmpty()?null:saved.get(0);if(old!=null&&old.optInt("acknowledged")==1&&fp.equals(old.optString("fingerprint")))return null;String client=old==null?"sleepwell-"+UUID.randomUUID():old.optString("client_id");long version=old==null?1:fp.equals(old.optString("fingerprint"))?old.optLong("version"):Math.addExact(old.optLong("version"),1);
  java.time.ZoneId zone=r.zone();List<RecordIntervals.Span> awake=new ArrayList<>(r.edit.awake);awake.addAll(r.pauses);List<HealthSleep.Stage> stages=new ArrayList<>();for(RecordIntervals.Span p:RecordIntervals.intersect(RecordIntervals.union(awake),r.edit.start,r.edit.end))stages.add(new HealthSleep.Stage(p.start,p.end,1));HealthSleep data=new HealthSleep(client,ownPackage,r.edit.start,r.edit.end,version,java.time.Instant.ofEpochMilli(r.edit.start).atZone(zone).getOffset().getTotalSeconds(),java.time.Instant.ofEpochMilli(r.edit.end).atZone(zone).getOffset().getTotalSeconds(),r.edit.tags.stream().anyMatch(t->t.equalsIgnoreCase("nap"))?"SleepWell nap":"SleepWell sleep",r.edit.note,stages);ContentValues v=new ContentValues();v.put("client_id",client);v.put("session",r.id);v.put("birth",signature);v.put("version",version);v.put("fingerprint",fp);v.put("payload",HealthSleepCodec.encode(data));v.put("remote_id",old==null?"":old.optString("remote_id"));v.put("acknowledged",0);if(store.getWritableDatabase().insertWithOnConflict("health_exports",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new android.database.sqlite.SQLiteException("Export identity could not be stored.");return new Export(client,r.id,signature,version,fp,data,r.manual());}
 public void admit(Export item){check();if(!exists(item.session)||!birth(Records.get(store,item.session)).equals(item.birth)||!fingerprint(item.session).equals(item.fingerprint))throw new IllegalStateException("Sleep changed while preparing export. Sync again.");}
 public boolean ack(Export item,String remoteId){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{boolean result=ackInside(item,remoteId);db.setTransactionSuccessful();return result;}finally{db.endTransaction();}}
 private boolean ackInside(Export item,String remoteId){check();if(remoteId==null||remoteId.isBlank()||remoteId.length()>512)throw new IllegalStateException("Health Connect returned no sleep identity; retry is safe.");ContentValues v=new ContentValues();v.put("remote_id",remoteId);v.put("acknowledged",1);int updated=store.getWritableDatabase().update("health_exports",v,"client_id=? AND version=? AND fingerprint=?",new String[]{item.client,""+item.version,item.fingerprint});if(updated!=1)throw new IllegalStateException("Export ownership changed. Health Connect may have received the earlier version.");return exists(item.session)&&fingerprint(item.session).equals(item.fingerprint);}
 public List<String> retired(){List<String> out=new ArrayList<>();check();for(JSONObject row:store.rows("SELECT * FROM health_exports")){long id=row.optLong("session");if(!exists(id)||!birth(Records.get(store,id)).equals(row.optString("birth")))out.add(row.optString("client_id"));}return out;}
 public void retiredDone(String client){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{check();db.delete("health_exports","client_id=?",new String[]{client});db.setTransactionSuccessful();}finally{db.endTransaction();}}
 void notice(String message,String error){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{check();if(message!=null)value("last_result",message);value("last_error",error);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public void finished(long at,String summary){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{check();value("last_sync",""+at);value("last_result",summary);value("last_error","");db.setTransactionSuccessful();}finally{db.endTransaction();}}
}
